[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01)" = 'reminder to sato: aoi 2026-01-01 10:00-11:00' ] || { echo "remind --who"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
BOOKINGS=$t bash src/remind.sh --who 2>/dev/null; [ $? = 2 ] || { echo "--who without a name should exit 2"; fail=1; }
BOOKINGS=$t bash src/remind.sh --who sato 2026-02-02 >/dev/null; [ $? = 0 ] || { echo "day with no bookings should exit 0"; fail=1; }
